-- THE DAILY EXPORT READS A REGISTRY EVERY PULL REQUEST ADDS ROWS TO (it_engineer, 29 Sep 2026).
--
-- fn_table_export_list() was one VALUES list that every PR which created a table rewrote whole. On 29 Sep seven
-- PRs redefined it at once; each carried the list as its branch saw it, so the last one applied dropped the
-- others' tables until someone noticed. The list is now rows: public.table_export_registry, one row per public
-- table, EXPORTED (category = the subject it records) or EXCLUDED (category = why: secret, cache, log,
-- measurement, fixture, no_writer). A PR that creates a table INSERTS its row; nobody rewrites anybody's list.
--
-- MEASURED before this file: fn_table_export_list() returned 174 rows on production (read live 29 Sep 2026
-- 19:24 UTC, identical to the MANIFEST winner the_seat_playbooks_are_in_the_daily_export.sql). Those 174 are
-- seeded as they were. The exclusion JSON (scripts/checks/every_table_is_exported_or_explicitly_excluded.json)
-- moves in here too, so a table's export decision and its reason have one home.
--
-- THE BACKLOG, decided: 178 tables had a live writer, were never exported and carried the admitted category
-- "backlog". Each was decided on its columns and live row count (read 29 Sep 2026): 137 hold business records
-- (the ceo_* and seat_* decisions, disputes, sanctions bans, the close pack, supply gaps, website pages, the
-- trade taxonomy...) and are EXPORTED from today; 41 are a cache, log, measurement or secret and are EXCLUDED
-- with that reason. After this file: 312 exported (174 -> 312 with the registry itself; the count does not drop), 0 backlog.
--
-- fn_table_export_list() keeps its signature (CREATE OR REPLACE keeps its grant: service_role only) and reads
-- the registry. A registry row whose table is gone still fails the day loudly in backup/index.ts, as before.
--
-- HOW A PR ADDS A TABLE: in the file that creates it,
--   insert into public.table_export_registry (table_name, exported, category, reason, added_by) values
--     ('my_table', true, 'supplier', 'what it records', 'my_seat')
--   on conflict (table_name) do update set exported = excluded.exported, category = excluded.category,
--     reason = excluded.reason, added_by = excluded.added_by;
-- Never redefine fn_table_export_list(). scripts/checks/every_table_is_exported_or_explicitly_excluded.test.mjs
-- reads these rows from the SQL files (scripts/lib/table_export_registry.mjs) and fails on either mistake.

create table if not exists public.table_export_registry (
  table_name text primary key check (table_name ~ '^[a-z0-9_]+$'),
  exported   boolean not null,
  category   text not null check (btrim(category) <> ''),
  reason     text not null check (length(btrim(reason)) >= 10),
  added_by   text not null,
  added_at   timestamptz not null default now(),
  constraint table_export_registry_exclusion_has_a_known_reason
    check (exported or category in ('secret', 'cache', 'log', 'measurement', 'fixture', 'no_writer'))
);
comment on table public.table_export_registry is
  'One row per public table: exported by the daily export (category = subject) or excluded with its reason. PRs insert rows; fn_table_export_list() reads them.';
alter table public.table_export_registry enable row level security;
drop policy if exists table_export_registry_service_role_only on public.table_export_registry;
create policy table_export_registry_service_role_only on public.table_export_registry
  as permissive for all to public using (false) with check (false);
revoke all on public.table_export_registry from anon, authenticated;

on conflict (table_name) do update set exported = excluded.exported, category = excluded.category,
  reason = excluded.reason, added_by = excluded.added_by;

create or replace function public.fn_table_export_list()
returns table(table_name text, subject text, change_log text)
language sql stable
set search_path to 'public', 'pg_temp'
as $fn$
  select r.table_name, r.category,
         (select 'table_export_change' from public.table_export_change_tracked x where x.table_name = r.table_name)
    from public.table_export_registry r
   where r.exported
   order by r.table_name
$fn$;

-- VERDICT (read by apply_sql.mjs): the list did not drop, every exported table exists, nothing is left in backlog.
select case
  when (select count(*) from public.fn_table_export_list()) < 174
    then 'PROBE FAILED: fn_table_export_list returns ' || (select count(*) from public.fn_table_export_list()) || ', fewer than the 174 before'
  when exists (select 1 from public.table_export_registry r where r.exported and to_regclass('public.' || r.table_name) is null)
    then 'PROBE FAILED: exported but missing: ' || (select string_agg(r.table_name, ', ') from public.table_export_registry r
                                                   where r.exported and to_regclass('public.' || r.table_name) is null)
  when exists (select 1 from public.table_export_registry where category = 'backlog')
    then 'PROBE FAILED: a backlog row is left'
  else 'PROBE OK exported=' || (select count(*) from public.fn_table_export_list())
       || ' excluded=' || (select count(*) from public.table_export_registry where not exported) end as verdict;
